            visited.add(f)
            while stack:
                u = stack.pop()
                comp.append(u)
                for v in adj[u]:
                    if v not in visited:
                        visited.add(v)
                        stack.append(v)
            components.append(comp)

    total_independent_sets = 1
    for comp in components:
        comp_set = frozenset(comp)
        local_adj = {f: [v for v in adj[f] if v in comp_set] for f in comp_set}

        memo = {}
        def count_is_memo(nodes):
            if not nodes:
                return 1
            if nodes in memo:
                return memo[nodes]

            v = min(nodes, key=lambda x: len([n for n in local_adj[x] if n in nodes]))

            res = count_is_memo(frozenset(nodes - {v}))
            res += count_is_memo(frozenset(nodes - {v} - set(local_adj[v])))

            memo[nodes] = res
            return res

        total_independent_sets *= count_is_memo(comp_set)

    print(f"Total independent sets: {total_independent_sets}")

solve()
